import type { Clausule, Polisdata, PolisDetails, PolisId, PolisStatusNaam, PolisVersieId } from "#types";
import { Traverse } from "@asr-tools/utils";
import assert from "assert";

export default class Polis {
    /** De ruwe polisdata */
    readonly data: Polisdata;
    /** De ruwe polisdetails */
    readonly details: PolisDetails;

    constructor(polisdata: Polisdata, details: PolisDetails) {
        this.data = polisdata;
        this.details = details;

        assert(
            this.isStatusActief || this.isStatusGeenDekking || this.isStatusGeroyeerd,
            `Polis ${this.polisnummer} heeft een onbekende status: ${this.status}`
        );
    }

    // IDs
    get polisnummer(): PolisId {
        return this.data.externalIdentifier;
    }
    get actueleVersieId(): PolisVersieId {
        return this.data.policyVersionExtId;
    }

    // Status
    get status(): PolisStatusNaam { return this.data.policyStatusExtId; }
    get isStatusActief(): boolean { return this.status === "active"; }
    get isStatusGeenDekking(): boolean { return this.status === "coverageRevoked"; }
    get isStatusGeroyeerd(): boolean { return this.status === "deactivated"; }

    // Productversie
    get productVersie() { return this.veld("polGarageProductversieLs"); }
    get isConversie() { return this.productVersie === "conversie"; }
    get isSelling() { return this.productVersie === "selling"; }

    // Polishouder
    get polishouder() {
        const h = this.data.policyHolder;
        const a = h.address;
        return {
            naam: h.name,
            land: a?.countryRef?.country?.name,
            stad: a?.city,
            straat: a?.streetName,
            huisnummer: a?.houseNumber,
            postcode: a?.postalCode,
        };
    }

    // Intermediair
    get intermediair() {
        const i = this.data.intermediary;
        return { naam: i.name, emailAdres: i.emailAddress, id: i.externalIdentifier };
    }

    // Clausules
    get clausules(): Clausule[] {
        return this.data.conditionsAndClauses.clauseList;
    }
    heeftClausule(identifier: `V${number}`) {
        return this.clausules.some(clause => clause.name.startsWith(identifier));
    }

    // Helpers
    protected veld<T = string>(id: string) {
        return Traverse.matchByIdentifier(this.details.policyInstanceFieldList, id)?.value?.value as T | undefined;
    }
}